export const renderKpi=(e,t={})=>{if(!e)return;const n=e.querySelector(".lp-kpi-value"),s=e.querySelector(".lp-kpi-delta"),i=e.querySelector(".lp-kpi-subline");if(n){const e=t.formatted??t.value;n.textContent=null==e||""===e?"–":String(e)}if(s)if(s.classList.remove("is-up","is-down"),"number"==typeof t.change_pct){const e=t.change_pct>=0;s.classList.add(e?"is-up":"is-down"),s.textContent=`${e?"▲":"▼"} ${Math.abs(t.change_pct)}%`}else s.textContent="";i&&(i.textContent=t.subline??"")};